function model(p) {
  // A company adds one system a year. Worst case: every system exchanges data with every other one.
  // Point-to-point needs a link per pair, n(n-1)/2; a hub needs one connection per system, n.
  const n = Math.max(4, Math.min(12, Math.round(p.systems)));
  const hub = Math.round(p.architecture) === 1, sf = Math.round(p.names) === 1;
  const BASE = [['CRM', 'Health Cloud', 'Health Cloud'], ['Billing'], ['Claims'],
    ['Member portal', 'Experience Cloud portal', 'Exp. Cloud portal'], ['Data warehouse', 'Data Cloud', 'Data Cloud'],
    ['Marketing', 'Marketing Cloud', 'Mktg Cloud'], ['Care management', null, 'Care mgmt'], ['Pharmacy'],
    ['Provider directory', null, 'Provider dir.'], ['Analytics', 'CRM Analytics', 'CRM Analytics'], ['ERP'],
    ['Contact centre', 'Service Cloud contact centre', 'Service Cloud']];
  const hubName = sf ? 'MuleSoft Anypoint' : 'Integration hub';
  const Y = n - 1, growEnd = 9, step = growEnd / Y;
  const yearAt = y => +((y - 1) * step).toFixed(3);
  const systems = BASE.slice(0, n).map((b, i) => {
    const native = sf && !!b[1], name = native ? b[1] : b[0];
    const short = native ? b[2] : (b[0] === 'Care management' || b[0] === 'Provider directory') ? b[2] : name;
    const year = Math.max(1, i);
    return { id: 's' + i, index: i, name, short, salesforce: native, year, at: yearAt(year), team: name + ' team' };
  });
  const links = [];
  systems.forEach((s, j) => {
    const peers = hub ? ['hub'] : systems.slice(0, j).map(x => x.id);
    if (!hub && j === 0) return;
    const k = links.filter(l => l.year === s.year).length;
    peers.forEach((pid, q) => {
      const order = k + q, stagger = Math.min(0.12, step * 0.55 / Math.max(1, j));
      links.push({ id: s.id + '-' + pid, a: s.id, b: pid, year: s.year, at: +(s.at + 0.25 + order * stagger).toFixed(3) });
    });
  });
  const pts = c => c * (c - 1) / 2;
  const cap = hub ? hubName : 'point-to-point';
  const years = [];
  for (let y = 1; y <= Y; y++) {
    const c = y + 1, added = systems.filter(s => s.year === y);
    const total = links.filter(l => l.year <= y).length, fresh = links.filter(l => l.year === y).length;
    const names = added.map(s => s.name).join(' and ');
    let caption;
    if (y === 1) caption = hub
      ? 'Year 1: ' + names + ' go live, each connected once to ' + hubName + ': 2 connections (point-to-point would need 1).'
      : 'Year 1: ' + names + ' go live. One point-to-point link keeps customers and invoices in step.';
    else caption = hub
      ? 'Year ' + y + ': ' + names + ' joins with one connection to ' + hubName + '. +1, ' + total + ' in total (point-to-point: ' + pts(c) + ').'
      : 'Year ' + y + ': ' + names + ' joins and needs a link to each of the ' + (c - 1) + ' existing systems. +' + fresh + ', ' + total + ' in total.';
    years.push({ year: y, at: yearAt(y), systems: c, added: added.map(s => s.name), p2p: pts(c), hub: c, total, fresh, caption });
  }
  const changed = systems[1], changeAt = 9.6, soWhatAt = 11.8, duration = 14;
  const hit = links.filter(l => l.a === changed.id || l.b === changed.id);
  const impacted = hit.map((l, i) => ({ link: l.id, at: +(changeAt + 0.1 + i * Math.min(0.14, 1.4 / hit.length)).toFixed(3),
    team: hub ? (sf ? 'MuleSoft team' : 'Integration team') : systems.find(s => s.id === (l.a === changed.id ? l.b : l.a)).team }));
  const total = links.length, cnt = impacted.length;
  const change = { systemId: changed.id, name: changed.name, year: Y + 1, at: changeAt, impacted, count: cnt,
    p2pImpacted: n - 1, hubImpacted: 1, teams: impacted.map(x => x.team),
    caption: hub
      ? 'Year ' + (Y + 1) + ': ' + changed.name + ' retires its v1 API. Only the ' + changed.name + ' adapter in ' + hubName + ' changes: 1 integration, 1 team.'
      : 'Year ' + (Y + 1) + ': ' + changed.name + ' retires its v1 API. Every system wired to it breaks: ' + cnt + ' integrations, ' + cnt + ' teams doing rework.' };
  const soWhat = hub
    ? 'So what: ' + hubName + ' grew by one connection per system (' + n + ', versus ' + pts(n) + ' point-to-point) and kept the API change inside one adapter. The trade-off: the hub is now critical infrastructure to fund, run and govern.'
    : 'So what: ' + n + ' systems need ' + pts(n) + ' point-to-point integrations, and one API change breaks ' + (n - 1) + '. With a hub it is ' + n + ' connections and 1 fix. Effort grows with the square of the system count.';
  const summary = hub
    ? hubName + ': ' + n + ' systems, ' + total + ' connections; one API change touched 1 adapter.'
    : 'Point-to-point: ' + n + ' systems, ' + total + ' integrations; one API change broke ' + cnt + ' of them.';
  return {
    n, architecture: hub ? 'Integration hub' : 'Point-to-point', hub, hubName, salesforceNames: sf, systems, links, years,
    total, p2pTotal: pts(n), hubTotal: n, change, soWhat, soWhatAt, cap,
    duration, markers: years.map(y => y.at).concat([changeAt, soWhatAt]), summary
  };
}

checkCode:
function check(p) {
  const m = model(p), ids = new Set(m.systems.map(s => s.id).concat(m.hub ? ['hub'] : []));
  const formula = c => m.hub ? c : c * (c - 1) / 2;
  const yearsOk = m.years.every(y => y.total === formula(y.systems) && m.links.filter(l => l.year <= y.year).length === y.total);
  const real = m.links.every(l => ids.has(l.a) && ids.has(l.b) && l.a !== l.b);
  const unique = new Set(m.links.map(l => [l.a, l.b].sort().join('|'))).size === m.links.length;
  const want = m.hub ? 1 : m.n - 1;
  const impactOk = m.change.count === want && m.change.p2pImpacted === m.n - 1 && m.change.hubImpacted === 1;
  return {
    pass: yearsOk && real && unique && impactOk && m.total === formula(m.n),
    detail: m.architecture + ' with ' + m.n + ' systems: ' + m.total + ' integrations (formula ' + (m.hub ? 'n = ' : 'n(n-1)/2 = ') + formula(m.n) +
      '), every year matching its formula; ' + m.change.name + "'s API change impacts " + m.change.count + ' (expected ' + want + ', versus ' + (m.hub ? (m.n - 1) + ' point-to-point' : '1 with a hub') + ').'
  };
}
